document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("verifyForm"),t=document.getElementById("verifyInput"),n=document.getElementById("verifyResult");e.addEventListener("submit",e=>{e.preventDefault();const d=t.value.trim().toUpperCase(),r=IRWR.byId(d);n.innerHTML=r?`\n      <div class="cert-card reveal in">\n        <div class="cert-status">Verified record</div>\n        <h2>${IRWR.escapeHtml(r.title)}</h2>\n        <p>${IRWR.escapeHtml(r.holderName)} · ${IRWR.escapeHtml(r.country)}</p>\n        <p>${IRWR.escapeHtml(r.category)} · ${IRWR.escapeHtml(r.date)}</p>\n        <p class="cert-provenance">Originally recognized by GBR (Global Best of Records). Registered in IRWR under ID <strong>${IRWR.escapeHtml(r.id)}</strong>.</p>\n      </div>\n    `:`<div class="cert-not-found">No record found for "${IRWR.escapeHtml(d)}". Check the IRWR index number and try again.</div>`})});